/**
 * The only door between canon and the app. Everything here is generated by
 * scripts/import-canon from the snapshot in canon/. Components never state canon.
 */
import type { Cast, Decisions, Entry, Meta, Scene, Scenes, Tally } from '../scripts/lib/types';
import castJson from '../data/cast.json';
import decisionsJson from '../data/decisions.json';
import metaJson from '../data/meta.json';
import scenesJson from '../data/scenes.json';
import tallyJson from '../data/tally.json';

const modules = import.meta.glob<Entry>('../data/entries/*.json', { eager: true, import: 'default' });

export const entries: Entry[] = Object.values(modules).sort((a, b) => a.order - b.order);
export const entryById = new Map(entries.map((e) => [e.id, e]));
export const cast = castJson as Cast;
export const decisions = decisionsJson as Decisions;
export const meta = metaJson as unknown as Meta;
export const scenes = (scenesJson as Scenes).scenes;
export const scenesIntro = (scenesJson as Scenes).intro;
export const sceneById = new Map<string, Scene>(scenes.map((s) => [s.id, s]));
export const tally = tallyJson as Tally;
export const castBySlug = new Map(cast.rows.map((r) => [r.slug, r]));

export const isOpen = (e: Entry) => e.status === 'open';
export const fieldLabel = (f: string) => f.replace(/_/g, ' ');

export type { Entry, Scene, Segment, Block, CastRow, SceneSection } from '../scripts/lib/types';
